#include "bc-math-library.hh"

#if defined(GD_BC_PREPARSED_LIBRARY)
#  include <cassert>
#  include <cstdlib>

#  include "bc.hh"
#  include "math-library-image.hh"
#endif

#include <string_view>

namespace GD::Bc::Library {
// The generated bytes have static lifetime and are only read by the -l loader.
auto text() -> std::string_view { return {source, sizeof(source) - 1}; }

#if defined(GD_BC_PREPARSED_LIBRARY)
namespace {
#  include "bc-math-library-image.inc"

class ImageReader
{
public:
  explicit ImageReader(std::string_view bytes) : bytes_(bytes) {}

  auto byte() -> unsigned
  {
    assert(!bytes_.empty());
    auto const value = static_cast<unsigned char>(bytes_.front());
    bytes_.remove_prefix(1);
    return value;
  }

  auto word() -> unsigned
  {
    auto const low = byte();
    return low | (byte() << 8U);
  }

  auto operand() -> Instruction::Operand
  {
    constexpr std::string_view letters = "abcdefghijklmnopqrstuvwxyz";
    switch (static_cast<ImageOperand>(byte())) {
    case ImageOperand::string:
      return std::string(string());
    case ImageOperand::stream:
      return static_cast<Instruction::Stream>(byte());
    case ImageOperand::offset:
      return static_cast<Instruction::Offset>(word()) - image_offset_bias;
    case ImageOperand::location: {
      auto const file = string();
      auto const line = word();
      auto const column = word();
      return Location(file, line, column);
    }
    case ImageOperand::mask: {
      auto const variables = string();
      return VariableMask(variables, string());
    }
    case ImageOperand::unsigned_:
      return word();
    case ImageOperand::letter:
      return Letter(letters[byte()]);
    case ImageOperand::variable:
      return Variable(letters[byte()]);
    case ImageOperand::array:
      return Array(letters[byte()]);
    }
    std::abort();
  }

private:
  auto string() -> std::string_view
  {
    auto const size = word();
    assert(size <= bytes_.size());
    auto const value = bytes_.substr(0, size);
    bytes_.remove_prefix(size);
    return value;
  }

  std::string_view bytes_;
};
auto decode_item(std::string_view bytes) -> Instructions
{
  ImageReader reader(bytes);
  auto const count = reader.word();
  Instructions code;
  code.reserve(count);
  for (unsigned index = 0; index < count; ++index) {
    auto const opcode = static_cast<Instruction::Opcode>(reader.byte());
    if (Instruction::has_op2(opcode)) {
      auto const first = reader.operand();
      code.emplace_back(opcode, first, reader.operand());
    }
    else if (Instruction::has_op1(opcode)) {
      code.emplace_back(opcode, reader.operand());
    }
    else {
      code.emplace_back(opcode);
    }
  }
  return code;
}
}  // namespace

void load(VM& vm)
{
  constexpr std::string_view letters = "abcdefghijklmnopqrstuvwxyz";
  constexpr std::string_view bytes(image, sizeof(image) - 1);
  for (auto const& item : items) {
    auto const encoded = bytes.substr(item.begin, item.size);
    if (item.function < Letter::count_) {
      vm.defer_library_function(Letter(letters[item.function]), encoded, decode_item);
    }
    else {
      auto code = decode_item(encoded);
      if (!vm.execute(code)) {
        return;
      }
    }
  }
}
#endif
}  // namespace GD::Bc::Library
